common_head='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Wanderly — путеводитель по четырём странам: культура, природа и красивые места."><title>{title} — Wanderly</title><link rel="stylesheet" href="style.css"><script src="script.js" defer></script></head><body class="{theme}"><header class="site-header"><a class="logo" href="index.html"><b>W</b>wanderly<i>.</i></a><button class="menu-toggle" aria-label="Открыть меню" aria-expanded="false"><span></span><span></span></button><nav class="main-nav"><a href="index.html" data-word="home">Главная</a><a href="kyrgyzstan.html" data-word="kg">Кыргызстан</a><a href="usa.html" data-word="us">США</a><a href="spain.html" data-word="es">Испания</a><a href="japan.html" data-word="jp">Япония</a></nav><div class="tools"><label><span style="position:absolute;clip:rect(0,0,0,0)">Язык</span><select id="languageSelect" aria-label="Язык"><option value="ru">RU</option><option value="ky">KY</option><option value="en">EN</option><option value="es">ES</option><option value="ja">日本語</option></select></label><button class="theme-toggle" aria-label="Переключить тему">☾</button></div></header>'''
